nline\",\"dangerouslySetInnerHTML\":{\"__html\":\"devotee\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-4\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-mat\",{\"href\":\"/en/search/synonyms/?original=mat\",\"children\":[\"$\",\"em\",null,{\"children\":\"mat\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"My\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-5\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-yājī\",{\"href\":\"/en/search/synonyms/?original=yājī\",\"children\":[\"$\",\"em\",null,{\"children\":\"yājī\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"worshiper\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-6\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-mām\",{\"href\":\"/en/search/synonyms/?original=mām\",\"children\":[\"$\",\"em\",null,{\"children\":\"mām\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"unto Me\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-7\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-namas\",{\"href\":\"/en/search/synonyms/?original=namas\",\"children\":[\"$\",\"em\",null,{\"children\":\"namas\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-kuru\",{\"href\":\"/en/search/synonyms/?original=kuru\",\"children\":[\"$\",\"em\",null,{\"children\":\"kuru\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"offer obeisances\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-8\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-mām\",{\"href\":\"/en/search/synonyms/?original=mām\",\"children\":[\"$\",\"em\",null,{\"children\":\"mām\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"unto Me\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-9\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-eva\",{\"href\":\"/en/search/synonyms/?original=eva\",\"children\":[\"$\",\"em\",null,{\"children\":\"eva\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"completely\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-10\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-eṣyasi\",{\"href\":\"/en/search/synonyms/?original=eṣyasi\",\"children\":[\"$\",\"em\",null,{\"children\":\"eṣyasi\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"you will come\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-11\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-yuktvā\",{\"href\":\"/en/search/synonyms/?original=yuktvā\",\"children\":[\"$\",\"em\",null,{\"children\":\"yuktvā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"being absorbed\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-12\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-evam\",{\"href\":\"/en/search/synonyms/?original=evam\",\"children\":[\"$\",\"em\",null,{\"children\":\"evam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"thus\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-13\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ātmānam\",{\"href\":\"/en/search/synonyms/?original=ātmānam\",\"children\":\"$L32\"}]],\" — \",\"$L33\",\"; \"]}],\"$L34\"]}]}]]]}]\n"])self.__next_f.push([1,"2e:[\"$\",\"div\",\"2806-translation,2806-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L2a\",\"child-2810\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"Engage your mind always in thinking of Me, become My devotee, offer obeisances to Me and worship Me. Being completely absorbed in Me, surely you will come to Me.\"}}]}]}]]]}]\n35:T53b,In this verse it is clearly indicated that Kṛṣṇa consciousness is the only means of being delivered from the clutches of this contaminated material world. Sometimes unscrupulous commentators distort the meaning of what is clearly stated here: that all devotional service should be offered to the Supreme Personality of Godhead, Kṛṣṇa. Unfortunately, unscrupulous commentators divert the mind of the reader to that which is not at all feasible. Such commentators do not know that there is no difference between Kṛṣṇa’s mind and Kṛṣṇa. Kṛṣṇa is not an ordinary human being; He is Absolute Truth. His body, His mind and He Himself are one and absolute. It is stated in the Kūrma Purāṇa, as it is quoted by Bhaktisiddhānta Sarasvatī Gosvāmī in his Anubhāṣya comments on Caitanya-caritāmṛta (Fifth Chapter, Ādi-līlā, verses 41–48), deha-dehi-vibhedo ’yaṁ neśvare vidyate kvacit. This means that there is no difference in Kṛṣṇa, the Supreme Lord, between Himself and His body. But because the commentators do not know this science of Kṛṣṇa, they hide Kṛṣṇa and divide His personality from His mind or from His body. Although this is sheer ignorance of the science of Kṛṣṇa, some men make profit out of misleading people."])self.__next_f.push([1,"2f:[\"$\",\"div\",\"2806-purport,2806-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L2a\",\"child-2811\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$35\"}}]}],[\"$\",\"$L2a\",\"child-2812\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:1\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"There are some who are demonic; they also think of Kṛṣṇa, but enviously, just like King Kaṁsa, Kṛṣṇa’s uncle. He was also thinking of Kṛṣṇa always, but he thought of Kṛṣṇa as his enemy. He was always in anxiety, wondering when Kṛṣṇa would come to kill him. That kind of thinking will not help us. One should be thinking of Kṛṣṇa in devotional love. That is bhakti. One should cultivate the knowledge of Kṛṣṇa continuously. What is that favorable cultivation? It is to learn from a bona fide teacher. Kṛṣṇa is the Supreme Personality of Godhead, and we have several times explained that His body is not material, but is eternal, blissful knowledge. This kind of talk about Kṛṣṇa will help one become a devotee. Understanding Kṛṣṇa otherwise, from the wrong source, will prove fruitless.\"}}]}],[\"$\",\"$L2a\",\"child-2813\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:2\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"One should therefore engage his mind in the eternal form, the primal form of Kṛṣṇa; with conviction in his heart that Kṛṣṇa is the Supreme, he should engage himself in worship. There are hundreds of thousands of temples in India for the worship of Kṛṣṇa, and devotional service is practiced there. When such practice is made, one has to offer obeisances to Kṛṣṇa. One should lower his head before the Deity and engage his mind, his body, his activities – everything. That will make one fully absorbed in Kṛṣṇa without deviation. This will help one transfer to Kṛṣṇaloka. One should not be deviated by unscrupulous commentators. One must engage in the nine different processes of devotional service, beginning with hearing and chanting about Kṛṣṇa. Pure devotional service is the highest achievement of human society.\"}}]}],\"$L36\",\"$L37\",\"$L38\"]]}]\n"])self.__next_f.push([1,"39:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"27:[\"$\",\"div\",null,{\"id\":\"footer\",\"className\":\"mt-auto w-full max-w-7xl mx-auto pt-3 mb-6 text-sm text-vb-normal-text/80 text-center\",\"children\":[[\"$\",\"$L1f\",null,{\"donors\":\"Shweta Saxena; Gopalakrishnan Soundarajan;    Kuldip Persaud;  Raghava Chandra Dasa; Shubhangi Rajiv Panjiyar; Suparna Kotaru;  Rajendra and Geeta Ramchandani;  Jaykumar Prabhakar; Bharat Vyas; Shri Chander Mohan Gilhotra, HG Prashant Mukund Das, Shri Trilok Singh Grover, HG Bhakta Mitra Das, Laxmi Narayan Agarwal; Ronak Talati; Bhargav Ashok; Akiralali; Rajasa das; Riya and Tejal Chopade; Indradyumna Swami; Jai Devaki Parks;  Ashmi Chakraborty; Hari-kirtana das; Ramesta das; Prasad Buddhavarapu; Kresna Sucandra; Esekiel Jaggernauth\",\"locale\":\"en\"}],[\"$\",\"div\",null,{\"className\":\"w-full max-w-screen-xl mx-auto text-vb-normal-text mb-3\",\"children\":[[\"$\",\"a\",null,{\"target\":\"_blank\",\"rel\":\"noopener noreferrer\",\"href\":\"https://t.me/online_vedabase\",\"className\":\"text-vb-normal-text hover:text-vb-normal-text/60\",\"alt\":\"Vedabase Telegram\",\"aria-label\":\"Vedabase Telegram\",\"children\":[\"$\",\"svg\",null,{\"stroke\":\"currentColor\",\"fill\":\"currentColor\",\"strokeWidth\":\"0\",\"viewBox\":\"0 0 496 512\",\"className\":\"inline w-8 h-8 mr-4\",\"children\":[\"$undefined\",[[\"$\",\"path\",\"0\",{\"d\":\"M24