s/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":2845,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 10.4-5\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T455,Asammoha, freedom from doubt and delusion, can be achieved when one is not hesitant and when he understands the transcendental philosophy. Slowly but surely he becomes free from bewilderment. Nothing should be accepted blindly; everything should be accepted with care and with caution. Kṣamā, tolerance and forgiveness, should be practiced; one should be tolerant and excuse the minor offenses of others. Satyam, truthfulness, means that facts should be presented as they are, for the benefit of others. Facts should not be misrepresented. According to social conventions, it is said that one can speak the truth only when it is palatable to others. But that is not truthfulness. The truth should be spoken in a straightforward way, so that others will understand actually what the facts are. If a man is a thief and if people are warned that he is a thief, that is truth. Although sometimes the truth is unpalatable, one should not refrain from speaking it. Truthfulness demands that the facts be presented as they are for the benefit of others. That is the definition of truth.26:T4ea,Control of the senses means that the senses should not be used for unnecessary personal enjoyment. There is no prohibition against meeting the proper needs of the senses, but unnecessary sense enjoyment is detrimental for spiritual advancement. Therefore the senses should be restrained from unnecessary use. Similarly, one should restrain the mind from unnecessary thoughts; that is called śama. One should not spend one’s time pondering over earning money. That is a misuse of the thinking power. The mind should be used to understand the prime necessity of human beings, and that should be presented authoritatively. The power of thought should be developed in association with persons who are authorities in the scriptures, saintly persons and spiritual masters and those whose thinking is highly developed. Sukham, pleasure or happiness, should always be in that which is favorable for the cultivation of the spiritual knowledge of Kṛṣṇa consciousness. And similarly, that which is painful or which causes distress is that which is unfavorable for the cultivation of Kṛṣṇa consciousness. Anything favorable for the development of Kṛṣṇa consciousness should be accepted, and anything unfavorable should be rejected.27:T5e8,"])self.__next_f.push([1,"Bhava, birth, should be understood to refer to the body. As far as the soul is concerned, there is neither birth nor death; that we have discussed in the beginning of Bhagavad-gītā. Birth and death apply to one’s embodiment in the material world. Fear is due to worrying about the future. A person in Kṛṣṇa consciousness has no fear because by his activities he is sure to go back to the spiritual sky, back home, back to Godhead. Therefore his future is very bright. Others, however, do not know what their future holds; they have no knowledge of what the next life holds. So they are therefore in constant anxiety. If we want to get free from anxiety, then the best course is to understand Kṛṣṇa and be situated always in Kṛṣṇa consciousness. In that way we will be free from all fear. In the Śrīmad-Bhāgavatam (11.2.37) it is stated, bhayaṁ dvitīyābhiniveśataḥ syāt: fear is caused by our absorption in the illusory energy. But those who are free from the illusory energy, those who are confident that they are not the material body, that they are spiritual parts of the Supreme Personality of Godhead, and who are therefore engaged in the transcendental service of the Supreme Godhead, have nothing to fear. Their future is very bright. This fear is a condition of persons who are not in Kṛṣṇa consciousness. Abhayam, fearlessness, is possible only for one in Kṛṣṇa consciousness."])self.__next_f.push([1,"28:T4fc,Tuṣṭi, satisfaction, means that one should not be eager to gather more and more material goods by unnecessary activity. One should be satisfied with whatever is obtained by the grace of the Supreme Lord; that is called satisfaction. Tapas means austerity or penance. There are many rules and regulations in the Vedas which apply here, like rising early in the morning and taking a bath. Sometimes it is very troublesome to rise early in the morning, but whatever voluntary trouble one may suffer in this way is called penance. Similarly, there are prescriptions for fasting on certain days of the month. One may not be inclined to practice such fasting, but because of his determination to make advancement in the science of Kṛṣṇa consciousness, he should accept such bodily troubles when they are recommended. However, one should not fast unnecessarily or against Vedic injunctions. One should not fast for some political purpose; that is described in Bhagavad-gītā as fasting in ignorance, and anything done in ignorance or passion does not lead to spiritual advancement. Everything done in the mode of goodness does advance one, however, and fasting done in terms of the Vedic injunctions enriches one in spiritual knowledge.29:T7d4,"])self.__next_f.push([1,"As far as charity is concerned, one should give fifty percent of his earnings to some good cause. And what is a good cause? It is that which is conducted in terms of Kṛṣṇa consciousness. That is not only a good cause, but the best cause. Because Kṛṣṇa is good, His cause is also good. Thus charity should be given to a person who is engaged in Kṛṣṇa consciousness. According to the Vedic literature, it is enjoined that charity should be given to the brāhmaṇas. This practice is still followed, although not very nicely in terms of the Vedic injunction. But still the injunction is that charity should be given to the brāhmaṇas. Why? Because they are engaged in higher cultivation of spiritual knowledge. A brāhmaṇa is supposed to devote his whole life to understanding Brahman. Brahma jānātīti brāhmaṇaḥ: one who knows Brahman is called a brāhmaṇa. Thus charity is offered to the brāhmaṇas because they are always engaged in higher spiritual service and have no time to earn their livelihood. In the Vedic literature, charity is also to be awarded to one in the renounced order of life, the sannyāsī. The sannyāsīs beg from door to door, not for money but for missionary purposes. The system is that they go from door to door to awaken the householders from the slumber of ignorance. Because the householders are engaged in family affairs and have forgotten their actual purpose in life – awakening their Kṛṣṇa consciousness – it is the business of the sannyāsīs to go as beggars to the householders and encourage them to be Kṛṣṇa conscious. As it is said in the Vedas, one should awake and achieve what is due him in this human form of life. This knowledge and method is distributed by the sannyāsīs; hence charity is to be given to the renouncer of life, to the brāhmaṇas, and similar good causes, not to any whimsical cause."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":2845,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"4-5\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXTS 4-5\",\"advanced_view_url_path\":\"/en/library/bg/10/advanced-view/#bb2519\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/10/4-5/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/10/4-5/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/10/4-5/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/10/4-5/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/10/4-5/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/10/4-5/\"},{\"display_name\":\"Eesti keel (Estonian)\",\"language_code\":\"et\",\"enabled\":true,\"url_path\":\"/et/library/bg/10/4-5/\"},{\"display_name\":\"Suomen kieli (Finnish)\",\"language_code\":\"fi\",\"enabled\":false,\"url_path\":\"/fi/\"},{\"display_name\":\"Français (French)\",\"language_code\":\"fr\",\"enabled\":true,\"url_path\":\"/fr/library/bg/10/4-5/\"},{\"display_name\":\"Hrvatski (Croatian)\",\"language_code\":\"hr\",\"enabled\":true,\"url_path\":\"/hr/library/bg/10/4-5/\"},{\"display_name\":\"Magyar (Hungarian)\",\"language_code\":\"hu\",\"enabled\":true,\"url_path\":\"/h