],\"; \"]}]\n39:[\"$\",\"span\",\"wfwundefined-17\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-samatā\",{\"href\":\"/en/search/synonyms/?original=samatā\",\"children\":[\"$\",\"em\",null,{\"children\":\"samatā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"equilibrium\"}}],\"; \"]}]\n3a:[\"$\",\"span\",\"wfwundefined-18\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-tuṣṭiḥ\",{\"href\":\"/en/search/synonyms/?original=tuṣṭiḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"tuṣṭiḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"satisfaction\"}}],\"; \"]}]\n3b:[\"$\",\"span\",\"wfwundefined-19\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-tapaḥ\",{\"href\":\"/en/search/synonyms/?original=tapaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"tapaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"penance\"}}],\"; \"]}]\n3c:[\"$\",\"span\",\"wfwundefined-20\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-dānam\",{\"href\":\"/en/search/synonyms/?original=dānam\",\"children\":[\"$\",\"em\",null,{\"children\":\"dānam\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"charity\"}}],\"; \"]}]\n3d:[\"$\",\"span\",\"wfwundefined-21\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-yaśaḥ\",{\"href\":\"/en/search/synonyms/?original=yaśaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"yaśaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"fame\"}}],\"; \"]}]\n3e:[\"$\",\"span\",\"wfwundefined-22\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-ayaśaḥ\",{\"href\":\"/en/search/synonyms/?original=ayaśaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"ayaśaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"infamy\"}}],\"; \"]}]\n3f:[\"$\",\"span\",\"wfwundefined-23\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-bhavanti\",{\"href\":\"/en/search/synonyms/?original=bhavanti\",\"children\":[\"$\",\"em\",null,{\"children\":\"bhavanti\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"come about\"}}],\"; \"]}]\n40:[\"$\",\"span\",\"wfwundefined-24\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-bhāvāḥ\",{\"href\":\"/en/search/synonyms/?original=bhāvāḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"bhāvāḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"natures\"}}],\"; \"]}]\n41:[\"$\",\"span\",\"wfwundefined-25\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-bhūtānām\",{\"href\":\"/en/search/synonyms/?original=bhūtānām\",\"children\":[\"$\",\"em\",null,{\"children\":\"bhūtānām\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"of living entities\"}}],\"; \"]}]\n42:[\"$\",\"span\",\"wfwundefined-26\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-mattaḥ\",{\"href\":\"/en/search/synonyms/?original=mattaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"mattaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"from Me\"}}],\"; \"]}]\n43:[\"$\",\"span\",\"wfwunde"])self.__next_f.push([1,"fined-27\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-eva\",{\"href\":\"/en/search/synonyms/?original=eva\",\"children\":[\"$\",\"em\",null,{\"children\":\"eva\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"certainly\"}}],\"; \"]}]\n44:[\"$\",\"span\",\"wfwundefined-28\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-pṛthak\",{\"href\":\"/en/search/synonyms/?original=pṛthak\",\"children\":[\"$\",\"em\",null,{\"children\":\"pṛthak\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-vidhāḥ\",{\"href\":\"/en/search/synonyms/?original=vidhāḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"vidhāḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"variously arranged\"}}],\".\"]}]\n"])self.__next_f.push([1,"47:[\"$\",\"$L2e\",\"child-2855\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:4\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[[\"$\",\"em\",\"0\",{\"children\":\"Bhava,\"}],\" birth, should be understood to refer to the body. As far as the soul is concerned, there is neither birth nor death; that we have discussed in the beginning of \",[\"$\",\"em\",\"2\",{\"children\":\"Bhagavad-gītā.\"}],\" Birth and death apply to one’s embodiment in the material world. Fear is due to worrying about the future. A person in Kṛṣṇa consciousness has no fear because by his activities he is sure to go back to the spiritual sky, back home, back to Godhead. Therefore his future is very bright. Others, however, do not know what their future holds; they have no knowledge of what the next life holds. So they are therefore in constant anxiety. If we want to get free from anxiety, then the best course is to understand Kṛṣṇa and be situated always in Kṛṣṇa consciousness. In that way we will be free from all fear. In the \",[\"$\",\"$L20\",\"4\",{\"href\":\"/en/library/sb/11/2/37/\",\"children\":[[\"$\",\"em\",\"0\",{\"children\":\"Śrīmad-Bhāgavatam\"}],\" (11.2.37)\"]}],\" it is stated, \",[\"$\",\"em\",\"6\",{\"children\":\"bhayaṁ dvitīyābhiniveśataḥ syāt:\"}],\" fear is caused by our absorption in the illusory energy. But those who are free from the illusory energy, those who are confident that they are not the material body, that they are spiritual parts of the Supreme Personality of Godhead, and who are therefore engaged in the transcendental service of the Supreme Godhead, have nothing to fear. Their future is very bright. This fear is a condition of persons who are not in Kṛṣṇa consciousness. \",[\"$\",\"em\",\"8\",{\"children\":\"Abhayam,\"}],\" fearlessness, is possible only for one in Kṛṣṇa consciousness.\"]}]}]\n"])self.__next_f.push([1,"48:[\"$\",\"$L2e\",\"child-2856\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:5\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Ahiṁsā, nonviolence, means that one should not do anything which will put others into misery or confusion. Material activities that are promised by so many politicians, sociologists, philanthropists, etc., do not produce very good results because the politicians and philanthropists have no transcendental vision; they do not know what is actually beneficial for human society. Ahiṁsā means that people should be trained in such a way that the full utilization of the human body can be achieved. The human body is meant for spiritual realization, so any movement or any commissions which do not further that end commit violence on the human body. That which furthers the future spiritual happiness of the people in general is called nonviolence.\"}}]}]\n49:[\"$\",\"$L2e\",\"child-2857\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:6\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Samatā, equanimity, refers to freedom from attachment and aversion. To be very much attached or to be very much detached is not the best. This material world should be accepted without attachment or aversion. That which is favorable for prosecuting Kṛṣṇa consciousness should be accepted; that which is unfavorable should be rejected. That is called samatā, equanimity. A person in Kṛṣṇa consciousness has nothing to reject and nothing to accept save in terms of its usefulness in the prosecution of Kṛṣṇa consciousness.\"}}]}]\n50:T4fc,Tuṣṭi, satisfaction, means that one should not be eager to gather more and more material goods by unnecessary activity. One should be satisfied with whatever is obtained by the grace of the Supreme Lord; that is called satisfaction. Tapas means austerity or penance. There are many rules and regulations in the Vedas which apply here, like rising early in the morning and taking a bath. Sometimes it is very troublesome to rise early in the morning, but whatever voluntary trouble one may suffer in this way is called penance. Similarly, there are prescriptions for fasting on certain days of the month. One may not be inclined to practice such fasting, but because of his determination to make advancement in the science of Kṛṣṇa consciousness, he should accept such bodily troubles when they are recommended. However, one should not fast unnecessarily or against Vedic injunctions. One should not fast for some political purpose; that is described in Bhagavad-gītā as fasting in ignorance, and anything done in ignorance or passion does not lead to spiritual advancement. Everything done in the mode of goodness does advance one, however, and fasting done in terms of the Vedic injunctions enriches one in spiritual knowledge.4a:[\"$\",\"$L2e\",\"child-2858\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:7\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$50\"}}]}]\n51:T7d4,"])self.__next_f.push([1,"As far as charity is concerned, one should give fifty percent of his earnings to some good cause. And what is a good cause? It is that which is conducted in terms of Kṛṣṇa consciousness. That is not only a good cause, but the best cause. Because Kṛṣṇa is good, His cause is also good. Thus charity should be given to a person who is engaged in Kṛṣṇa consciousness. According to the Vedic literature, it is enjoined that charity should be given to the brāhmaṇas. This practice is still followed, although not very nicely in terms of the Vedic injunction. But still the injunction is that charity should be given to the brāhmaṇas. Why? Because they are engaged in higher cultivation of spiritual knowledge. A brāhmaṇa is supposed to devote his whole life to understanding Brahman. Brahma jānātīti brāhmaṇaḥ: one who knows Brahman is called a brāhmaṇa. Thus charity is offered to the brāhmaṇas because they are always engaged in higher spiritual service and have no time to earn their livelihood. In the Vedic literature, charity is also to be awarded to one in the renounced order of life, the sannyāsī. The sannyāsīs beg from door to door, not for money but for missionary purposes. The system is that they go from door to door to awaken the householders from the slumber of ignorance. Because the householders are engaged in family affairs and have forgotten their actual purpose in life – awakening their Kṛṣṇa consciousness – it is the business of the sannyāsīs to go as beggars to the householders and encourage them to be Kṛṣṇa conscious. As it is said in the Vedas, one should awake and achieve what is due him in this human form of life. This knowledge and method is distributed by the sannyāsīs; hence charity is to be given to the renouncer of life, to the brāhmaṇas, and similar good causes, not to any whimsical cause."])self.__next_f.push([1,"4b:[\"$\",\"$L2e\",\"child-2859\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:8\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$51\"}}]}]\n4c:[\"$\",\"$L2e\",\"child-2860\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:9\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Yaśas, fame, should be according to Lord Caitanya, who said that a man is famous when he is known as a great devotee. That is real fame. If one has become a great man in Kṛṣṇa consciousness and it is known, then he is truly famous. One who does not have such fame is infamous.\"}}]}]\n4d:[\"$\",\"$L2e\",\"child-2861\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:10\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"All these qualities are manifest throughout the universe in human society and in the society of the demigods. There are many forms of humanity on other planets, and these qualities are there. Now, for one who wants to advance in Kṛṣṇa consciousness, Kṛṣṇa creates all these qualities, but the person develops them himself from within. One who engages in the devotional service of the Supreme Lord develops all the good qualities, as arranged by the Supreme Lord.\"}}]}]\n4e:[\"$\",\"$L2e\",\"child-2862\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:11\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Of whatever we find, good or bad, the origin is Kṛṣṇa. Nothing can manifest itself in this material world which is not in Kṛṣṇa. That is knowledge; although we know that things are differently situated, we should realize that everything flows from Kṛṣṇa.\"}}]}]\n"])(function(){function c(){var b=a.contentDocument||(a.contentWindow&&a.contentWindow.document);if(b){var d=b.createElement(''script'');d.innerHTML="window.__CF$cv$params={r:''a34058872e06f501'',t:''MTc4ODIyNDUwOA==''};var a=document.createElement(''script'');a.src=''/cdn-cgi/challenge-platform/scripts/jsd/main.js'';document.getElementsByTagName(''head'')[0].appendChild(a);";b.getElementsByTagName(''head'')[0].appendChild(d)}}if(document.body){var a=document.createElement(''iframe'');a.height=1;a.width=1;a.style.position=''absolute'';a.style.top=0;a.style.left=0;a.style.border=''none'';a.style.visibility=''hidden'';document.body.appendChild(a);if(''loading''!==document.readyState)c();else if(window.addEventListener)document.addEventListener(''DOMContentLoaded'',c);else{var e=document.onreadystatechange||function(){};document.onreadystatechange=function(b){e(b);''loading''!==document.readyState&&(document.onreadystatechange=e,c())}}}})();', 'https://vedabase.io/en/library/bg/10/4-5/', true)
